Database & Storage.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(database_storage, "Database & Storage") {
    Component(Amazon_Aurora_Serverless_v2_DB_Instance, "Amazon Aurora Serverless v2 DB Instance", "Amazon Aurora PostgreSQL with pgcrypto", "Stores transactional and audit data with append-only tables and immutable cryptographic triggers.")
    Component(AWS_RDS_Proxy, "AWS RDS Proxy", "AWS RDS Proxy", "Manages connection pooling for high-throughput concurrency from microservices.")
}

Rel(AWS_RDS_Proxy, Amazon_Aurora_Serverless_v2_DB_Instance, "Proxies and pools database connections")

@enduml

Caching Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container(FraudScoringEngineContainer, "Fraud Scoring Engine Container", "Go or Rust", "Evaluates card-not-present payment authorizations.")

Container_Boundary(CachingLayer, "Caching Layer") {
    Component(FeatureStoreCacheComponent, "Feature Store Cache Component", "Amazon ElastiCache with Redis OSS", "Provides low-latency feature lookups for the fraud scoring engine.")
    Component(RateLimiterComponent, "Rate Limiter Component", "Amazon ElastiCache with Redis OSS", "Enforces sliding window rate limiting for incoming authorization requests.")
}

Rel(FraudScoringEngineContainer, FeatureStoreCacheComponent, "Redis Protocol")
Rel(FraudScoringEngineContainer, RateLimiterComponent, "Redis Protocol")
@enduml
